INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BUCKLEY_MANDAEANS','secondary scholarship','Jorunn Jacobsen Buckley, The Mandaeans: Ancient Texts and Modern People (Oxford University Press, 2002)','Mandaean light-world/dark-world parallels for the cross-tradition cognate links')
INSERT INTO _e VALUES
 ('ENT_MANICH_PANTHEON','Manichaean Pantheon (Lightworld Hierarchy)','Collective','Pantheon','Manichaean','Cosmological hierarchy of the Realm of Light: the Father of Greatness and the successive Evocations deployed in the cosmic drama of the mixing and rescue of Light.','A','Connectivity hub for the Manichaean cohort; a structural collective node grouping the Lightworld emanations described in the Kephalaia and Psalm-Book, not an attested cult-figure. Prefix ENT_MANICH_ matches the existing tradition roster (distinct from Mandaean ENT_MAN_).');
INSERT INTO entities (entity_id,canonical_name,tradition,entity_type,category,primary_domains,cult_scope,evidence_confidence,review_status,inclusion_basis,earth_association_score,chthonic_flag,serpent_flag,short_note)
INSERT INTO _s VALUES
 ('ENT_MANICH_PANTHEON','SRC_MANICHAEAN_KEPHALAIA','scholarly attestation','attestation');
INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_MANICH_PANTHEON','','Connectivity hub for the Manichaean cohort; a structural collective node grouping the Lightworld emanations described in the Kephalaia and Psalm-Book, not an attested cult-figure. Prefix ENT_MANICH_ matches the existing tradition roster (distinct from Mandaean ENT_MAN_).');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_MANICH_FATHER_GREATNESS','member_of','ENT_MANICH_PANTHEON','high','The Father of Greatness heads the Realm of Light from which all Evocations proceed; apex of the Lightworld hierarchy hub. Kephalaia.'),
 ('ENT_MANICH_MOTHER_LIFE','member_of','ENT_MANICH_PANTHEON','high','The Mother of Life, First Evocation of the Father; member of the Lightworld hierarchy. Lieu, Manichaeism in the Later Roman Empire.'),
 ('ENT_MANICH_PRIMAL_MAN','member_of','ENT_MANICH_PANTHEON','high','Primal Man (Ohrmazd), the Father''s champion evoked through the Mother of Life; core Lightworld figure of the First Creation.'),
 ('ENT_MANICH_LIVING_SPIRIT','member_of','ENT_MANICH_PANTHEON','high','The Living Spirit (Mihryazd), Evocation of the Second Creation who rescues Primal Man; member of the Lightworld hierarchy.'),
 ('ENT_MANICH_THIRD_MESSENGER','member_of','ENT_MANICH_PANTHEON','high','The Third Messenger, Evocation of the Third Creation who orchestrates liberation of the swallowed Light; member of the Lightworld hierarchy.'),
 ('ENT_MANICH_MAIDEN_LIGHT','member_of','ENT_MANICH_PANTHEON','high','The Maiden of Light (Virgin of Light) accompanies the Third Messenger in the seduction of the archons; Lightworld member. Kephalaia.'),
 ('ENT_MANICH_JESUS_SPLENDOUR','member_of','ENT_MANICH_PANTHEON','high','Jesus the Splendour, the revealer who awakens Adam, is one of the saving Evocations of the Lightworld hierarchy.'),
 ('ENT_MANICH_COLUMN_GLORY','member_of','ENT_MANICH_PANTHEON','high','The Column of Glory (Perfect Man / Milky Way), cosmic channel of ascending Light; a Lightworld structure within the hierarchy.'),
 ('ENT_MANICH_GREAT_BUILDER','member_of','ENT_MANICH_PANTHEON','high','The Great Builder (Ban Rabba) constructs the New Paradise for the rescued Light; Lightworld Evocation.'),
 ('ENT_MANICH_LIGHT_MIND','member_of','ENT_MANICH_PANTHEON','high','The Light Mind (Nous) governs the Church and the soul of the believer; Lightworld member. Kephalaia ch. 38.'),
 ('ENT_MANICH_KING_GLORY','member_of','ENT_MANICH_PANTHEON','medium','King of Glory, one of the Five Sons of the Living Spirit governing the cosmic apparatus; Lightworld hierarchy member.'),
 ('ENT_MANICH_KING_HONOUR','member_of','ENT_MANICH_PANTHEON','medium','King of Honour, one of the Five Sons of the Living Spirit, watcher over the heavens; Lightworld member.'),
 ('ENT_MANICH_ADAMAS','member_of','ENT_MANICH_PANTHEON','medium','Adamas of Light, a Son of the Living Spirit who combats the dark powers; Lightworld member.'),
 ('ENT_MANICH_FIVE_SONS','member_of','ENT_MANICH_PANTHEON','high','The Five Sons of Primal Man (the Light elements / soul-armour) deployed and swallowed in the cosmic battle; Lightworld collective member.'),
 ('ENT_MANICH_CALL_ANSWER','member_of','ENT_MANICH_PANTHEON','medium','Call and Answer, paired Lightworld hypostases mediating the rescue of Primal Man; members of the hierarchy.'),
 ('ENT_MANICH_PORTER','member_of','ENT_MANICH_PANTHEON','medium','The Porter (Splenditenens / Omophoros), one of the Five Sons of the Living Spirit who supports the cosmos; Lightworld member.'),
 ('ENT_MANICH_KEEPER_SPLENDOUR','member_of','ENT_MANICH_PANTHEON','medium','Keeper of Splendour, one of the Five Sons of the Living Spirit; Lightworld member of the second-creation hierarchy.'),
 ('ENT_MANICH_LAST_STATUE','member_of','ENT_MANICH_PANTHEON','medium','The Last Statue (Andrias), the eschatological assembling of redeemed Light at the consummation; Lightworld figure of the hierarchy. Kephalaia.'),
 ('ENT_MANICH_LIGHT_PARTICLES','member_of','ENT_MANICH_PANTHEON','low','The dispersed Light particles (the suffering Living Self) are of the substance of the Realm of Light; grouped structurally under the Lightworld hub.'),
 ('ENT_MANICH_TWIN','member_of','ENT_MANICH_PANTHEON','medium','The Twin (Syzygos), Mani''s heavenly counterpart mediating revelation; Lightworld member. Cologne Mani Codex.'),
 ('ENT_MANICH_FRIEND_LIGHTS','member_of','ENT_MANICH_PANTHEON','medium','The Friend of the Lights, an early Evocation of the second-creation series; Lightworld member. Theodore bar Konai.'),
 ('ENT_MANICH_MOTHER_LIFE','emanates_from','ENT_MANICH_FATHER_GREATNESS','high','First Evocation: the Father of Greatness evokes the Mother of Life. Standard three-evocation cosmogony in the Kephalaia and Theodore bar Konai''s summary.'),
 ('ENT_MANICH_PRIMAL_MAN','emanates_from','ENT_MANICH_MOTHER_LIFE','high','The Mother of Life evokes Primal Man (Ohrmazd) as the Father''s warrior against Darkness; second link of the First Creation chain.'),
 ('ENT_MANICH_PRIMAL_MAN','child_of','ENT_MANICH_MOTHER_LIFE','high','Primal Man is called the son of the Mother of Life in the Psalm-Book and Kephalaia; filial language of the first Evocation series.'),
 ('ENT_MANICH_LIVING_SPIRIT','emanates_from','ENT_MANICH_MOTHER_LIFE','high','Second Creation: in response to Primal Man''s prayer the Father (with the Mother of Life) evokes the Living Spirit to descend and rescue him. Lieu.'),
 ('ENT_MANICH_FIVE_SONS','child_of','ENT_MANICH_PRIMAL_MAN','high','The Five Sons (the five Light elements / soul-armour: Air, Wind, Light, Water, Fire) are the sons Primal Man arms himself with and offers to the Darkness. Theodore bar Konai.'),
 ('ENT_MANICH_MAIDEN_LIGHT','emanates_from','ENT_MANICH_THIRD_MESSENGER','high','The Maiden of Light is evoked with the Third Messenger and displayed to the archons to release the Light through the seduction of the rulers. Theodore bar Konai.'),
 ('ENT_MANICH_COLUMN_GLORY','emanates_from','ENT_MANICH_THIRD_MESSENGER','medium','The Column of Glory, ascending channel of liberated Light, is established within the third-creation apparatus deployed by the Third Messenger. Kephalaia.'),
 ('ENT_MANICH_JESUS_SPLENDOUR','emanates_from','ENT_MANICH_THIRD_MESSENGER','medium','Jesus the Splendour is sent in the wake of the Third Messenger to awaken Adam and reveal gnosis; among the later Evocations of the saving sequence. Lieu; Kephalaia.'),
 ('ENT_MANICH_LIGHT_MIND','emanates_from','ENT_MANICH_JESUS_SPLENDOUR','medium','The Light Mind (the Great Nous) proceeds from Jesus the Splendour to organize the Church and indwell the elect. Kephalaia ch. 38 (''On the Light Mind'').'),
 ('ENT_MANICH_GREAT_BUILDER','participates_in_creation','ENT_MANICH_WORLD_LIGHT','medium','The Great Builder constructs the New Earth / New Paradise as a repository for the rescued Light, an extension of the World of Light. Lieu.'),
 ('ENT_MANICH_PORTER','participates_in_creation','ENT_MANICH_WORLD_LIGHT','low','The Porter upholds the cosmos fashioned by the Living Spirit from the bodies of the defeated archons, the apparatus that filters Light back toward the World of Light.'),
 ('ENT_MANICH_FATHER_GREATNESS','dwells_in','ENT_MANICH_WORLD_LIGHT','high','The Father of Greatness dwells in the Realm/World of Light with the aeons; standard Manichaean topography. Kephalaia; Psalm-Book.'),
 ('ENT_MANICH_LAST_STATUE','eschatological_role','ENT_MANICH_WORLD_LIGHT','medium','At the end the Last Statue gathers the last salvageable Light and ascends to the World of Light, sealing the separation of the two natures. Lieu.'),
 ('ENT_MANICH_LIGHT_PARTICLES','rescued_by','ENT_MANICH_THIRD_MESSENGER','medium','The Light Particles (the soul / Living Self mixed into matter) are the object of rescue accomplished through the Third Messenger''s evocations. Kephalaia.'),
 ('ENT_MANICH_MANI','reception_of','ENT_MANICH_JESUS_SPLENDOUR','medium','Mani received his revelation through his heavenly Twin, identified with the syzygos sent by Jesus the Splendour / the Paraclete; Mani''s apostolate continues the saving revelation. Cologne Mani Codex.'),
 ('ENT_MANICH_TWIN','revealed_by','ENT_MANICH_JESUS_SPLENDOUR','medium','The Twin (Syzygos / al-Tawm), Mani''s divine counterpart who delivers the revelation, is associated with the saving emanation of Jesus the Splendour / the Light Mind. Cologne Mani Codex.'),
 ('ENT_MANICH_FIVE_DARK_WORLDS','opposes','ENT_MANICH_WORLD_LIGHT','high','The Five Worlds of Darkness stand in eternal opposition to the World of Light; the two-principle dualism foundational to Manichaeism. Kephalaia.'),
 ('ENT_MANICH_ARCHONS','ruled_by','ENT_MANICH_KING_DARKNESS','high','The Archons (rulers/abortions of darkness) are subordinate powers of the realm ruled by the King of Darkness. Lieu.'),
 ('ENT_MANICH_DEMONS','member_of','ENT_MANICH_FIVE_DARK_WORLDS','medium','The Demons are denizens of the Five Worlds of Darkness, offspring of the dark elements. Kephalaia.'),
 ('ENT_MANICH_AZ','member_of','ENT_MANICH_ARCHONS','medium','Az, the demoness of concupiscence/greed who drives the propagation of bodies to keep Light imprisoned, belongs to the powers of darkness. Middle Persian Manichaean texts; Lieu.'),
 ('ENT_MANICH_MATTER','opposes','ENT_MANICH_LIGHT_PARTICLES','high','Matter is the dark principle that imprisons and opposes the Light particles; the central soteriological conflict of mixing. Kephalaia; Psalm-Book.'),
 ('ENT_MANICH_JESUS_PATIBILIS','aligned_with','ENT_MANICH_JESUS_SPLENDOUR','medium','Jesus patibilis (suffering, immanent Light) and Jesus the Splendour (transcendent revealer) are two aspects of the multiple Manichaean Jesus-figure; aligned as facets of the same name. Lieu.'),
 ('ENT_MANICH_WORLD_LIGHT','aligned_with','ENT_MAN_WORLD_LIGHT','low','Cross-tradition typological parallel: the Manichaean World/Realm of Light and the Mandaean World of Light (alma d-nhura) are cognate Mesopotamian gnostic light-realm concepts; aligned (not identical). Note homonym/parallel for reviewer. Lieu; Buckley, The Mandaeans.'),
 ('ENT_MANICH_KING_DARKNESS','aligned_with','ENT_MAN_WORLD_DARKNESS','low','Cross-tradition typological parallel: the Manichaean realm/King of Darkness corresponds to the Mandaean World of Darkness as cognate dualist counter-realms in the shared Mesopotamian gnostic milieu. Buckley; Lieu.');
